window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6b2ef6a18efd868d"]={"versions": [{"id": "FIG-6b2ef6a18efd868d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des zyklischen Hauptfunktionsablaufs (<code>V2xGn_MainFunction</code>) im AUTOSAR-Classic-Architekturkontext. Das Diagramm visualisiert die Interaktion zwischen dem Basic Software Scheduler (<code>SchM</code>), dem GeoNetworking-Modul (<code>V2xGn</code>) und dem V2X-Management-Modul (<code>V2xM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (jeweils mit dem Stereotyp <code>«module»</code> versehen):</p>\n<ul class=\"fig-list\"><li><code>SchM</code>: Schedule Manager, Aufrufer der periodischen Hauptfunktion.\n</li><li><code>V2xGn</code>: V2X GeoNetworking BSW-Modul, Empfänger des Scheduler-Aufrufs.\n</li><li><code>V2xM</code>: V2X Management BSW-Modul, Bereitsteller von Positions- und Zeitinformationen.\n</li></ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>V2xGn_MainFunction()</code>: Synchrone BSW-Scheduler-Schnittstelle zur zyklischen Ausführung von <code>V2xGn</code>.\n</li><li><code>V2xM_GetPositionAndTime(Std_ReturnType, V2x_GnLocalPositionVectorType*)</code>: Synchroner Funktionsaufruf von <code>V2xGn</code> an <code>V2xM</code> zur Abfrage aktueller Zeit- und Positionsvektordaten mit Rückgabewert <code>Std_ReturnType</code> und Zeiger auf <code>V2x_GnLocalPositionVectorType</code>.\n</li><li><code>GeoNetworking Protocol Handling()</code>: Modulinterne Operation / Selbstaufruf innerhalb von <code>V2xGn</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SchM</code> initiiert den periodischen Zyklus durch synchronen Aufruf von <code>V2xGn_MainFunction()</code> auf der Lebenslinie von <code>V2xGn</code>.\n</li><li><code>V2xGn</code> aktiviert seine Ausführung und ruft synchron <code>V2xM_GetPositionAndTime(Std_ReturnType, V2x_GnLocalPositionVectorType*)</code> am Modul <code>V2xM</code> auf.\n</li><li><code>V2xM</code> führt die Abfrage aus und antwortet über eine gestrichelte Rückkehrkante an <code>V2xGn</code>.\n</li><li>Nach Erhalt der Positions- und Zeitdaten triggert <code>V2xGn</code> intern den Selbstaufruf <code>GeoNetworking Protocol Handling()</code>.\n</li><li>Nach Abschluss der internen Protokollverarbeitung kehrt der Kontrollfluss via gestrichelter Rückkehrkante von <code>V2xGn</code> an <code>SchM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe für den zyklischen Aufrufablauf der BSW-Hauptfunktion <code>V2xGn_MainFunction</code>.\n</li><li>Verbindliche Schnittstellenabhängigkeit: <code>V2xGn</code> erfordert für das GeoNetworking-Handling zwingend die Bereitstellung von Positions- und Zeitdaten durch das Modul <code>V2xM</code> über <code>V2xM_GetPositionAndTime</code> vor Beginn der Protokollverarbeitung.\n</li><li>Implementierer müssen sicherstellen, dass der Puffer/Zeiger für <code>V2x_GnLocalPositionVectorType</code> bereitgestellt und der Status <code>Std_ReturnType</code> ausgewertet wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a4f0e768992d0884", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des zyklischen Hauptfunktionsablaufs (<code>V2xGn_MainFunction</code>) im AUTOSAR-Classic-Architekturkontext. Das Diagramm visualisiert die Interaktion zwischen dem Basic Software Scheduler (<code>SchM</code>), dem GeoNetworking-Modul (<code>V2xGn</code>) und dem V2X-Management-Modul (<code>V2xM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (jeweils mit dem Stereotyp <code>«module»</code> versehen):</p>\n<ul class=\"fig-list\"><li><code>SchM</code>: Schedule Manager, Aufrufer der periodischen Hauptfunktion.\n</li><li><code>V2xGn</code>: V2X GeoNetworking BSW-Modul, Empfänger des Scheduler-Aufrufs.\n</li><li><code>V2xM</code>: V2X Management BSW-Modul, Bereitsteller von Positions- und Zeitinformationen.\n</li></ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>V2xGn_MainFunction()</code>: Synchrone BSW-Scheduler-Schnittstelle zur zyklischen Ausführung von <code>V2xGn</code>.\n</li><li><code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType**)</code>: Synchroner Funktionsaufruf von <code>V2xGn</code> an <code>V2xM</code> zur Abfrage aktueller Zeit- und Positionsdaten mit Rückgabewert <code>Std_ReturnType</code> und Doppelzeiger auf <code>V2xM_PositionAndTimeType</code>.\n</li><li><code>GeoNetworking Protocol Handling()</code>: Modulinterne Operation / Selbstaufruf innerhalb von <code>V2xGn</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SchM</code> initiiert den periodischen Zyklus durch synchronen Aufruf von <code>V2xGn_MainFunction()</code> auf der Lebenslinie von <code>V2xGn</code>.\n</li><li><code>V2xGn</code> aktiviert seine Ausführung und ruft synchron <code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType**)</code> am Modul <code>V2xM</code> auf.\n</li><li><code>V2xM</code> führt die Abfrage aus und antwortet über eine gestrichelte Rückkehrkante an <code>V2xGn</code>.\n</li><li>Nach Erhalt der Positions- und Zeitdaten triggert <code>V2xGn</code> intern den Selbstaufruf <code>GeoNetworking Protocol Handling()</code>.\n</li><li>Nach Abschluss der internen Protokollverarbeitung kehrt der Kontrollfluss via gestrichelter Rückkehrkante von <code>V2xGn</code> an <code>SchM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe für den zyklischen Aufrufablauf der BSW-Hauptfunktion <code>V2xGn_MainFunction</code>.\n</li><li>Verbindliche Schnittstellenabhängigkeit: <code>V2xGn</code> erfordert für das GeoNetworking-Handling zwingend die Bereitstellung von Positions- und Zeitdaten durch das Modul <code>V2xM</code> über <code>V2xM_GetPositionAndTime</code> vor Beginn der Protokollverarbeitung.\n</li><li>Implementierer müssen die geänderte C-Signatur mit Doppelzeiger auf <code>V2xM_PositionAndTimeType</code> beachten, über die <code>V2xM</code> die Speicheradresse der Datenstruktur an <code>V2xGn</code> übergibt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-00a0d8fec97540f0", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Darstellung des zyklischen Hauptfunktionsablaufs (<code>V2xGn_MainFunction</code>) im AUTOSAR-Classic-Architekturkontext. Das Diagramm visualisiert die Interaktion zwischen dem Basic Software Scheduler (<code>SchM</code>), dem GeoNetworking-Modul (<code>V2xGn</code>) und dem V2X-Management-Modul (<code>V2xM</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (jeweils mit dem Stereotyp <code>«module»</code> versehen):</p>\n<ul class=\"fig-list\"><li><code>SchM</code>: Schedule Manager, Aufrufer der periodischen Hauptfunktion.\n</li><li><code>V2xGn</code>: V2X GeoNetworking BSW-Modul, Empfänger des Scheduler-Aufrufs.\n</li><li><code>V2xM</code>: V2X Management BSW-Modul, Bereitsteller von Positions- und Zeitinformationen.\n</li></ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen und Operationen:</p>\n<ul class=\"fig-list\"><li><code>V2xGn_MainFunction()</code>: Synchrone BSW-Scheduler-Schnittstelle zur zyklischen Ausführung von <code>V2xGn</code>.\n</li><li><code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType**)</code>: Synchroner Funktionsaufruf von <code>V2xGn</code> an <code>V2xM</code> zur Abfrage aktueller Zeit- und Positionsdaten mit Rückgabewert <code>Std_ReturnType</code> und Doppelzeiger auf <code>V2xM_PositionAndTimeType</code>.\n</li><li><code>GeoNetworking Protocol Handling()</code>: Modulinterne Operation / Selbstaufruf innerhalb von <code>V2xGn</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>SchM</code> initiiert den periodischen Zyklus durch synchronen Aufruf von <code>V2xGn_MainFunction()</code> auf der Lebenslinie von <code>V2xGn</code>.\n</li><li><code>V2xGn</code> aktiviert seine Ausführung und ruft synchron <code>V2xM_GetPositionAndTime(Std_ReturnType, V2xM_PositionAndTimeType**)</code> am Modul <code>V2xM</code> auf.\n</li><li><code>V2xM</code> führt die Abfrage aus und antwortet über eine gestrichelte Rückkehrkante an <code>V2xGn</code>.\n</li><li>Nach Erhalt der Positions- und Zeitdaten triggert <code>V2xGn</code> intern den Selbstaufruf <code>GeoNetworking Protocol Handling()</code>.\n</li><li>Nach Abschluss der internen Protokollverarbeitung kehrt der Kontrollfluss via gestrichelter Rückkehrkante von <code>V2xGn</code> an <code>SchM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe für den zyklischen Aufrufablauf der BSW-Hauptfunktion <code>V2xGn_MainFunction</code>.\n</li><li>Verbindliche Schnittstellenabhängigkeit: <code>V2xGn</code> erfordert für das GeoNetworking-Handling zwingend die Bereitstellung von Positions- und Zeitdaten durch das Modul <code>V2xM</code> über <code>V2xM_GetPositionAndTime</code> vor Beginn der Protokollverarbeitung.\n</li><li>Implementierer müssen die geänderte C-Signatur mit Doppelzeiger auf <code>V2xM_PositionAndTimeType</code> beachten, über die <code>V2xM</code> die Speicheradresse der Datenstruktur an <code>V2xGn</code> übergibt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6b2ef6a18efd868d", "to": "FIG-a4f0e768992d0884", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Parameter-/Signaturänderung bei Schnittstelle <code>V2xM_GetPositionAndTime</code>: Der Typ des zweiten Parameters wurde von <code>V2x_GnLocalPositionVectorType*</code> auf <code>V2xM_PositionAndTimeType**</code> geändert.\n</li></ul>"}, {"from": "FIG-a4f0e768992d0884", "to": "FIG-00a0d8fec97540f0", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
